sealed class LiliaFfiException: kotlin.Exception() {
    
    class Storage(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class InvalidInput(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class NotFound(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Conflict(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Closed(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Timeout(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Unsupported(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    class Generic(
        
        val v1: kotlin.String
        ) : LiliaFfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LiliaFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): LiliaFfiException = FfiConverterTypeLiliaFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLiliaFfiError : FfiConverterRustBuffer<LiliaFfiException> {
    override fun read(buf: ByteBuffer): LiliaFfiException {
        

        return when(buf.getInt()) {
            1 -> LiliaFfiException.Storage(
                FfiConverterString.read(buf),
                )
            2 -> LiliaFfiException.InvalidInput(
                FfiConverterString.read(buf),
                )
            3 -> LiliaFfiException.NotFound(
                FfiConverterString.read(buf),
                )
            4 -> LiliaFfiException.Conflict(
                FfiConverterString.read(buf),
                )
            5 -> LiliaFfiException.Closed(
                FfiConverterString.read(buf),
                )
            6 -> LiliaFfiException.Timeout(
                FfiConverterString.read(buf),
                )
            7 -> LiliaFfiException.Unsupported(
                FfiConverterString.read(buf),
                )
            8 -> LiliaFfiException.Generic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LiliaFfiException): ULong {
        return when(value) {
            is LiliaFfiException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Conflict -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Closed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Unsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is LiliaFfiException.Generic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: LiliaFfiException, buf: ByteBuffer) {
        when(value) {
            is LiliaFfiException.Storage -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.InvalidInput -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.NotFound -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Conflict -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Closed -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Timeout -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Unsupported -> {
                buf.putInt(7)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is LiliaFfiException.Generic -> {
                buf.putInt(8)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




